export const money=n=>Number(n).toFixed(Number.isInteger(Number(n))?0:2);
export function quotaLabel(p){if(p.capacityConflict)return `${p.capacityValues.join(' / ')} GB · 容量标注有差异`;if(p.quotaPeriod==='year-total')return `${p.quotedGb??p.gb??'—'} GB / 年度总额`;if(p.quotaPeriod==='unknown')return `${p.quotedGb??'—'} GB · 重置待核实`;if(!Number.isFinite(p.gb))return '容量待核实';return `${p.gb} GB${p.quotaPeriod==='month'?(p.resetDays?` / ${p.resetDays}天`:' / 月'):' / 总额度'}`;}
export function monthlyPlans(b){return b.plans.filter(p=>p.cycle==='月付'&&p.quotaPeriod==='month'&&Number.isFinite(p.gb)&&p.gb>0).sort((a,b)=>a.price-b.price);}
export function monthlyReferencePlan(b){return (b.referencePriceIncludesUnknownQuota?b.plans.filter(p=>p.cycle==='月付'&&Number.isFinite(p.price)&&p.price>0):monthlyPlans(b)).sort((a,b)=>a.price-b.price)[0];}
export function unitPrice(p){return !p.noMonthlyUnitPrice&&p.quotaPeriod==='month'&&!p.capacityConflict&&Number.isFinite(p.gb)&&p.gb>0?(p.price/p.gb).toFixed(3):null;}
export function excluded(b){return b.planAttribution==='disputed'||['kosing','flyv'].includes(b.id);}
export function eligiblePlan(b,p){return !excluded(b)&&!p.capacityConflict&&p.cycle==='月付'&&p.quotaPeriod==='month'&&Number.isFinite(p.gb)&&p.gb>0&&!/限时|限量|活动/.test(p.name)&&!(b.id==='yuzhou'&&p.name==='星云月付小包');}
export function selectCandidates(brands,{budget,usage,multiplier=1,margin=0}){if(![budget,usage,multiplier,margin].every(Number.isFinite)||budget<=0||usage<=0||multiplier<1||margin<0||margin>100)throw new Error('请输入有效的预算、用量、倍率与余量。');const required=usage*multiplier*(1+margin/100);const matches=[];for(const b of brands){const p=b.plans.filter(p=>eligiblePlan(b,p)&&p.price<=budget&&p.gb>=required).sort((a,b)=>a.price-b.price)[0];if(p)matches.push({brand:b,plan:p,required,remaining:p.gb-required});}return{required,matches};}
